# Each pair should extend in BOTH directions along the line connecting them

def extend_diagonal_both_ways(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))

    out = [row[:] for row in grid]

    # Find all pairs of same-color cells that are diagonally adjacent
    # For each pair, extend in both directions along that diagonal
    extended_pairs = set()  # Track (min_pos, max_pos, color) to avoid duplicates

    for r in range(h):
        for c in range(w):
            for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == grid[r][c] and grid[r][c] != bg:
                        # Found diagonal pair
                        p1, p2 = ((r,c), grid[r][c]), ((nr,nc), grid[nr][nc])
                        if p1 > p2:
                            p1, p2 = p2, p1

                        # Don't duplicate same pair in different direction
                        pair_key = (p1[0], p2[0], p1[1])
                        if pair_key not in extended_pairs:
                            extended_pairs.add(pair_key)

                            # Extend FROM p2 in direction (dr, dc) (same as from p1 to p2)
                            arr, acr, nrr, ncr = p2[0][0], p2[0][1], p2[1][0], p2[1][1]
                            while 0 <= arr+dr < h and 0 <= acr+dc < w:
                                if out[arr+dr][acr+dc] == bg:
                                    out[arr+dr][acr+dc] = arr
                                    arr += dr
                                    acr += dc
                                else:
                                    break

                            # Extend FROM p1 in direction (-dr, -dc) (opposite direction)
                            arr, acr, nrr, ncr = p1[0][0], p1[0][1], p1[1][0], p1[1][1]
                            while 0 <= arr-dr < h and 0 <= acr-dc < w:
                                if out[arr-dr][acr-dc] == bg:
                                    out[arr-dr][acr-dc] = arr
                                    arr -= dr
                                    acr -= dc
                                else:
                                    break

    return out

