import json

# Test input
test_input = [
    [4]*21 for _ in range(23)
]
test_input[15][11] = 5
test_input[15][12] = 8
test_input[16][11] = 9
test_input[16][12] = 2
test_input[17][10] = 9
test_input[17][13] = 2

print("Test input non-background cells:")
for r in range(23):
    for c in range(21):
        if test_input[r][c] != 4:
            print(f"  ({r},{c})={test_input[r][c]}")

# Check for vertical pairs (same column, consecutive rows with same color)
print("\nChecking for vertical same-color pairs:")
vertical_pairs = []
bg = 4
for c in range(21):
    for r in range(23-1):
        if test_input[r][c] == test_input[r+1][c] and test_input[r][c] != bg:
            vertical_pairs.append(((r,c), (r+1,c), test_input[r][c]))

if vertical_pairs:
    print(f"  Found vertical pairs: {vertical_pairs}")
else:
    print("  No vertical same-color pairs")

# Check for horizontal pairs (same row, consecutive columns with same color)
print("\nChecking for horizontal same-color pairs:")
horizontal_pairs = []
for r in range(23):
    for c in range(21-1):
        if test_input[r][c] == test_input[r][c+1] and test_input[r][c] != bg:
            horizontal_pairs.append(((r,c), (r,c+1), test_input[r][c]))

if horizontal_pairs:
    print(f"  Found horizontal pairs: {horizontal_pairs}")
else:
    print("  No horizontal same-color pairs")

# Check for diagonal pairs (dr=1, dc=1 or dr=1, dc=-1)
print("\nChecking for diagonal same-color pairs:")
diagonal_pairs = []
for r in range(23):
    for c in range(21):
        for dr, dc in [(1,1), (1,-1), (-1,1), (-1,-1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 23 and 0 <= nc < 21:
                if test_input[nr][nc] == test_input[r][c] and test_input[r][c] != bg:
                    diagonal_pairs.append(((r,c), (nr,nc), test_input[r][c]))

print(f"  Found diagonal pairs: {diagonal_pairs}")

